/**
 * App templates: Node script projects built on the MIT SDK, generated by
 * `gullycore new <name> --template airdrop | locks`.
 *
 * Unlike the hook templates (Solidity rendered from a permission set), these
 * are ordinary TypeScript files kept as real files under `assets/apps/`, so the
 * CLI's test suite can compile them against the SDK exactly as a generated
 * project will. What is rendered here is only what varies per project: the
 * package manifest (name, how the SDK is resolved), the README and the
 * environment template.
 *
 * Rules every app template keeps, and the tests check:
 *   - dependencies are MIT only: `@gullylabs/core-sdk`, `viem`, and `tsx` /
 *     `@types/node` for development; no GPL package, no agent or wallet SDK;
 *   - a dry run is the default; sending needs `--execute` AND `PRIVATE_KEY`;
 *   - every transaction is simulated with its exact bytes before it is sent;
 *   - keys are read only from the environment, never from a flag.
 */

import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { dirname, join, posix, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

import { remappingPath } from "../util/fsx.js";

export interface AppScript {
  /** `npm run <name>`. */
  readonly name: string;
  /** Source file under `src/`. */
  readonly file: string;
  readonly describe: string;
  /** A copy-pasteable example invocation (after `npm run <name> --`). */
  readonly example: string;
  /** True when the script can send transactions (and so honours `--execute`). */
  readonly writes: boolean;
}

export interface AppTemplate {
  readonly id: string;
  readonly label: string;
  readonly description: string;
  readonly scripts: readonly AppScript[];
  /** The `GULLYCORE_*` address overrides the scripts read, with the address-book key each replaces. */
  readonly contracts: readonly { readonly env: string; readonly key: string; readonly contract: string }[];
  /** Paragraphs for the README, after the quickstart. */
  readonly notes: readonly string[];
}

const AIRDROP: AppTemplate = {
  id: "airdrop",
  label: "airdrop",
  description: "Node project: CSV -> multisend batches, or a Merkle drop + claims file (dry run by default)",
  scripts: [
    {
      name: "multisend",
      file: "multisend.ts",
      describe: "push native or an ERC-20 to every CSV row, in atomic batches of up to 1,000",
      example: "--csv recipients.csv --token native",
      writes: true,
    },
    {
      name: "drop",
      file: "drop.ts",
      describe: "build the Merkle tree and claims file, then create and fund a claimable drop",
      example: "--csv recipients.csv --token 0x<token> --days 90 --uri ipfs://<cid-of-claims.json>",
      writes: true,
    },
    {
      name: "holders",
      file: "holders.ts",
      describe: "read a token's holders from Transfer logs (checked against totalSupply at the snapshot) and write a recipients CSV",
      example: "--holders-of 0x<token> --token native --mode pro-rata --amount 10",
      writes: false,
    },
    {
      name: "check-claims",
      file: "check-claims.ts",
      describe: "verify a claims file (and, with --drop, against the root the drop stores)",
      example: "--file claims.json --drop 0x<drop>",
      writes: false,
    },
  ],
  contracts: [
    { env: "GULLYCORE_MULTISEND", key: "multisend", contract: "GullyCoreMultisend" },
    { env: "GULLYCORE_DROP_FACTORY", key: "dropFactory", contract: "GullyCoreDropFactory" },
  ],
  notes: [
    "**Multisend pushes.** You pay the gas and every recipient is paid in your transaction. Each call is atomic: one address that refuses makes the whole batch revert, and nothing is half-sent. An ERC-20 moves straight from you to each recipient, so the script approves `GullyCoreMultisend` for the exact sum, never an unlimited amount. Each call pays the contract's flat fee once.",
    "**A Merkle drop is pulled.** The drop stores one root; recipients claim and pay their own gas. `npm run drop` writes `claims.json` (every account's index, amount and proof) before anything is sent. Host that file (IPFS or any https server) and pass its URI with `--uri`: it becomes the drop's `metadataURI`, and a Gully Core site's claim page (`/app/airdrop/<drop>`) fetches it from there. The host does not need to be trusted: a claimer rebuilds the root from the file and compares it with the drop's. After the expiry nothing can be claimed and the creator may sweep the rest.",
    "**Airdrop to a token's holders.** `npm run holders` reduces the token's Transfer logs to balances at a snapshot block and refuses to write anything unless they add up to `totalSupply()` at that block (a scan that started after the token's first mint, or a rebasing token, never yields a partial list). Pro-rata and equal splits round down; the remainder is printed and not sent. The Vault, pool managers, LP lockers, lock contracts and the zero/dead addresses are skipped by default, from the SDK address book.",
    "**Amounts are exact.** `100.5` of an 18-decimal token is parsed digit by digit, never through a float, and a value with more decimals than the token has is an error. Every CSV problem is reported with its line number; nothing is dropped silently.",
  ],
};

const LOCKS: AppTemplate = {
  id: "locks",
  label: "locks",
  description: "Node project: time-lock a liquidity position, lock or vest a token, read lock status (dry run by default)",
  scripts: [
    {
      name: "lock-position",
      file: "lock-position.ts",
      describe: "time-lock a CL position NFT until a date (fees keep flowing to the lock owner)",
      example: "--token-id 42 --unlock +180d",
      writes: true,
    },
    {
      name: "vest",
      file: "vest.ts",
      describe: "lock an ERC-20 or native: a plain time-lock, or cliff + linear vesting",
      example: "--token 0x<token> --amount 1000000 --beneficiary 0x<team> --cliff-days 182 --duration-days 730",
      writes: true,
    },
    {
      name: "status",
      file: "status.ts",
      describe: "what is locked in a pool (share of ACTIVE liquidity) or of a token (share of supply)",
      example: "--token 0x<token>",
      writes: false,
    },
  ],
  contracts: [
    { env: "GULLYCORE_POSITION_LOCK", key: "positionLock", contract: "GullyCorePositionLock" },
    { env: "GULLYCORE_TOKEN_LOCK", key: "tokenLock", contract: "GullyCoreTokenLock" },
  ],
  notes: [
    "**Position locks.** Until the unlock date nobody - not the lock owner, not the protocol's Safe, not the contract - can remove liquidity from the position or move the NFT. The lock owner keeps collecting its swap fees, can extend the lock but never shorten it, hands it on two-step, and withdraws the NFT whole after the date. The script approves the lock for the ONE position, never `setApprovalForAll`.",
    "**What \"% of active liquidity locked\" means.** A CL pool has no LP token. The one pool-wide figure core keeps is the liquidity at the current tick; `npm run status -- --pool <id>` reports the locked, in-range share of it, exact at the block read. It says nothing about liquidity outside the current price and moves when the price moves.",
    "**Token locks and vesting.** Nothing before the cliff, then linear from start to end; a plain time-lock is start = cliff = end. The schedule is fixed at creation and no key can shorten, revoke or redirect it. The script approves the exact amount, never an unlimited one.",
  ],
};

export const APP_TEMPLATES: readonly AppTemplate[] = [AIRDROP, LOCKS];

export function findAppTemplate(id: string): AppTemplate | undefined {
  const wanted = id.trim().toLowerCase();
  return APP_TEMPLATES.find((t) => t.id === wanted);
}

export function appTemplateIds(): string[] {
  return APP_TEMPLATES.map((t) => t.id);
}

/** The only packages a generated app may depend on. Every one is MIT. */
export const APP_DEPENDENCY_LICENCES: Readonly<Record<string, string>> = {
  "@gullylabs/core-sdk": "MIT",
  viem: "MIT",
  tsx: "MIT",
  "@types/node": "MIT",
};

export interface AppContext {
  readonly projectName: string;
  readonly template: AppTemplate;
  /** `file:<relative path to packages/sdk>` inside a checkout, else a registry range. */
  readonly sdkDependency: string;
  readonly cliVersion: string;
}

/* ----------------------------------------------------------------- render --- */

export function renderAppPackageJson(ctx: AppContext): string {
  const scripts: Record<string, string> = {};
  for (const s of ctx.template.scripts) scripts[s.name] = `tsx src/${s.file}`;
  const pkg = {
    name: ctx.projectName,
    version: "0.1.0",
    private: true,
    description: `${ctx.template.label}: generated by create-gully-core-hook ${ctx.cliVersion} (gullycore new --template ${ctx.template.id})`,
    license: "MIT",
    type: "module",
    engines: { node: ">=20.12" },
    scripts,
    dependencies: {
      "@gullylabs/core-sdk": ctx.sdkDependency,
      viem: "^2.21.0",
    },
    devDependencies: {
      "@types/node": "^22.7.0",
      tsx: "^4.19.0",
    },
  };
  return `${JSON.stringify(pkg, null, 2)}\n`;
}

export function renderAppTsconfig(): string {
  const cfg = {
    compilerOptions: {
      target: "ES2022",
      lib: ["ES2022"],
      module: "NodeNext",
      moduleResolution: "NodeNext",
      strict: true,
      noUncheckedIndexedAccess: true,
      exactOptionalPropertyTypes: true,
      noUnusedLocals: true,
      skipLibCheck: true,
      noEmit: true,
      types: ["node"],
    },
    include: ["src"],
  };
  return `${JSON.stringify(cfg, null, 2)}\n`;
}

export function renderAppEnvExample(ctx: AppContext): string {
  const overrides = ctx.template.contracts.map((c) => `# ${c.env}=0x...   # ${c.contract}; overrides the address book's \`${c.key}\``).join("\n");
  return `# Copy to .env (git-ignored). The scripts read ONLY these variables; keys are never flags.

# Required: the chain is whatever this endpoint answers.
RPC_URL=http://127.0.0.1:8545

# Only for --execute. Leave unset for a dry run.
# PRIVATE_KEY=0x...

# Optional: simulate a dry run as this address without a key.
# FROM=0x...

# Optional: contract addresses for a local devnet. On a chain in the SDK's address book
# they are read from it; \`null\` there means "not deployed" and the scripts say so.
${overrides}
`;
}

export function renderAppGitignore(): string {
  return `node_modules/
.env
.env.*
!.env.example
claims*.json
`;
}

export function renderAppReadme(ctx: AppContext): string {
  const t = ctx.template;
  const rows = t.scripts.map((s) => `| \`npm run ${s.name}\` | ${s.describe} | ${s.writes ? "dry run unless `--execute`" : "reads only"} |`).join("\n");
  const examples = t.scripts.map((s) => `npm run ${s.name} -- ${s.example}`).join("\n");
  const contracts = t.contracts.map((c) => `- \`${c.contract}\`: address book key \`${c.key}\`, override \`${c.env}\``).join("\n");
  return `# ${ctx.projectName}

Generated by \`gullycore new --template ${t.id}\` (create-gully-core-hook ${ctx.cliVersion}). ${t.description}.

Built on \`@gullylabs/core-sdk\` and viem, both MIT. Nothing
here imports GPL code, so this project is yours under any licence you choose.

## Quickstart

${ctx.sdkDependency.startsWith("file:") ? `The SDK is linked from your Gully Core checkout (\`${ctx.sdkDependency}\`): build it once with
\`npm install && npm run build\` in that directory, then install here.

` : ""}\`\`\`bash
npm install
cp .env.example .env        # set RPC_URL; PRIVATE_KEY only when you are ready to send
${t.id === "airdrop" ? "cp recipients.example.csv recipients.csv   # format only: add your own rows\n" : ""}${t.scripts.map((s) => `npm run ${s.name} -- --help`).join("\n")}
\`\`\`

| script | what it does | sends? |
| ------ | ------------ | ------ |
${rows}

\`\`\`bash
${examples}
\`\`\`

## How the scripts behave

- **Dry run by default.** Without \`--execute\` a script reads, validates, prints the plan and simulates every
  transaction it can (as \`PRIVATE_KEY\`'s address, or \`FROM\`). A step that depends on an earlier one (a transfer
  after its approval) is reported as not simulable until that step is mined.
- **Simulate, then send.** With \`--execute\` each transaction is simulated with its exact bytes, sent, and its
  receipt checked before the next one. The first failure stops the plan; a revert is named from the contract's ABI.
- **Keys only from the environment.** \`PRIVATE_KEY\` is read from the environment (or \`.env\`); a key passed as a
  flag is refused, because flags end up in shell history.
- **Exact approvals.** An ERC-20 approval is for the exact amount the plan moves, never unlimited, and is skipped when
  the allowance already covers it.

## The contracts, and their fees

${contracts}

Addresses come from the SDK's address book for the chain \`RPC_URL\` answers. \`null\` there means the contract is not
deployed on that chain, and the script stops and says so rather than guessing. On a local devnet, set the override.

Every action pays a flat native fee **charged by the contract**, whoever calls it and however: through this project,
the SDK, your own code or a block explorer. The scripts read the fee live and send the higher of the fee in force and
any announced increase; the contract refunds the surplus in the same transaction. The fee's owner (the protocol's Safe)
can change it only inside an immutable cap, an increase only after a public notice.

${t.notes.join("\n\n")}

## Security checklist before \`--execute\` on a real chain

- [ ] Run the dry run and read every line of the plan: recipients, amounts, dates, fee.
- [ ] Use a key that holds only what this run needs. Never reuse a deployer or treasury key.
- [ ] Check \`RPC_URL\` points at the chain you mean; the scripts print the chain id they connected to.
- [ ] Keep \`.env\` out of version control (it is in \`.gitignore\`); never paste a key into a command.
`;
}

/* ------------------------------------------------------------------ files --- */

/** Locates `assets/apps`, both when running from `dist/` and from `src/`. */
export function findAppAssets(): string {
  const here = dirname(fileURLToPath(import.meta.url));
  for (const candidate of [join(here, "..", "assets", "apps"), join(here, "..", "..", "assets", "apps"), join(here, "..", "..", "..", "assets", "apps")]) {
    if (existsSync(join(candidate, "_shared", "src", "lib", "chain.ts"))) return resolve(candidate);
  }
  throw new Error("could not find the bundled app templates (assets/apps); this looks like a broken install");
}

function walk(dir: string, base: string, out: string[]): void {
  for (const name of readdirSync(dir).sort()) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) walk(full, base, out);
    else out.push(relative(base, full).split(sep).join(posix.sep));
  }
}

/** Every file of a generated app project: `[relative POSIX path, contents]`, in a stable order. */
export function appFiles(ctx: AppContext, assets: string = findAppAssets()): ReadonlyArray<readonly [string, string]> {
  const files: [string, string][] = [
    ["package.json", renderAppPackageJson(ctx)],
    ["tsconfig.json", renderAppTsconfig()],
    [".env.example", renderAppEnvExample(ctx)],
    [".gitignore", renderAppGitignore()],
    ["README.md", renderAppReadme(ctx)],
  ];
  for (const root of [join(assets, "_shared"), join(assets, ctx.template.id)]) {
    const rels: string[] = [];
    walk(root, root, rels);
    for (const rel of rels) files.push([rel, readFileSync(join(root, rel), "utf8").replace(/\r\n/g, "\n")]);
  }
  return files;
}

/**
 * How the generated project resolves the SDK: `file:` to a checkout's
 * `packages/sdk` when one is found near the output,
 * else the registry range.
 */
export function sdkDependencyFor(targetDir: string, searchFrom: readonly string[] = []): string {
  for (const start of [targetDir, ...searchFrom]) {
    let dir = resolve(start);
    for (;;) {
      const candidate = join(dir, "packages", "sdk", "package.json");
      if (existsSync(candidate)) {
        try {
          const name = (JSON.parse(readFileSync(candidate, "utf8")) as { name?: unknown }).name;
          if (name === "@gullylabs/core-sdk") {
            // Relative when near (the project moves with its checkout), absolute when far.
            return `file:${remappingPath(targetDir, dirname(candidate))}`;
          }
        } catch {
          // not a readable manifest; keep walking
        }
      }
      const parent = dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  }
  return "^0.3.0";
}
